module FetchUnit (
  output wire [9:0]    io_imemAddr,
  input  wire [255:0]  io_imemData,
  output wire [255:0]  io_exBundle,
  output wire          io_exValid,
  input  wire          io_jump_valid,
  input  wire [9:0]    io_jump_payload,
  input  wire          io_halt,
  input  wire          io_start,
  input  wire          io_stall,
  input  wire          io_replayStall,
  input  wire          io_matrixStall,
  input  wire          io_memBusy,
  output wire [9:0]    io_pc,
  output wire          io_running,
  output wire          io_halted,
  input  wire          clk,
  input  wire          reset
);
  localparam CoreState_IDLE = 2'd0;
  localparam CoreState_RUNNING = 2'd1;
  localparam CoreState_HALT_DRAIN = 2'd2;
  localparam CoreState_HALTED = 2'd3;

  wire       [9:0]    _zz_io_imemAddr;
  reg        [1:0]    state;
  reg        [9:0]    pc;
  wire                cycleActive;
  reg        [255:0]  exBundleReg;
  reg                 exValidReg;
  reg                 startupBubble;
  reg                 stallReleaseBubble;
  wire                when_FetchUnit_l91;
  wire                when_FetchUnit_l115;
  wire                when_FetchUnit_l150;
  `ifndef SYNTHESIS
  reg [79:0] state_string;
  `endif


  assign _zz_io_imemAddr = (pc - 10'h001);
  `ifndef SYNTHESIS
  always @(*) begin
    case(state)
      CoreState_IDLE : state_string = "IDLE      ";
      CoreState_RUNNING : state_string = "RUNNING   ";
      CoreState_HALT_DRAIN : state_string = "HALT_DRAIN";
      CoreState_HALTED : state_string = "HALTED    ";
      default : state_string = "??????????";
    endcase
  end
  `endif

  assign cycleActive = (state == CoreState_RUNNING);
  assign when_FetchUnit_l91 = (! io_memBusy);
  assign io_imemAddr = (io_stall ? _zz_io_imemAddr : pc);
  assign when_FetchUnit_l115 = (! io_stall);
  assign when_FetchUnit_l150 = ((io_replayStall && cycleActive) && (! io_matrixStall));
  assign io_exBundle = exBundleReg;
  assign io_exValid = (exValidReg && (! io_halt));
  assign io_pc = pc;
  assign io_running = cycleActive;
  assign io_halted = (state == CoreState_HALTED);
  always @(posedge clk) begin
    if(reset) begin
      state <= CoreState_IDLE;
      pc <= 10'h0;
      exBundleReg <= 256'h0;
      exValidReg <= 1'b0;
      startupBubble <= 1'b0;
      stallReleaseBubble <= 1'b0;
    end else begin
      case(state)
        CoreState_IDLE : begin
          if(io_start) begin
            state <= CoreState_RUNNING;
            pc <= 10'h0;
            startupBubble <= 1'b1;
          end
        end
        CoreState_RUNNING : begin
          if(io_halt) begin
            if(io_memBusy) begin
              state <= CoreState_HALT_DRAIN;
            end else begin
              state <= CoreState_HALTED;
            end
          end
        end
        CoreState_HALT_DRAIN : begin
          if(when_FetchUnit_l91) begin
            state <= CoreState_HALTED;
          end
        end
        default : begin
          if(io_start) begin
            state <= CoreState_RUNNING;
            pc <= 10'h0;
            startupBubble <= 1'b1;
          end
        end
      endcase
      if(when_FetchUnit_l115) begin
        if(cycleActive) begin
          if(startupBubble) begin
            startupBubble <= 1'b0;
            exValidReg <= 1'b0;
            pc <= (pc + 10'h001);
          end else begin
            if(stallReleaseBubble) begin
              stallReleaseBubble <= 1'b0;
              exValidReg <= 1'b0;
            end else begin
              if(io_jump_valid) begin
                pc <= io_jump_payload;
                exValidReg <= 1'b0;
                exBundleReg <= 256'h0;
              end else begin
                if(io_halt) begin
                  exValidReg <= 1'b0;
                end else begin
                  exBundleReg <= io_imemData;
                  exValidReg <= 1'b1;
                  pc <= (pc + 10'h001);
                end
              end
            end
          end
        end else begin
          exValidReg <= 1'b0;
        end
      end
      if(when_FetchUnit_l150) begin
        stallReleaseBubble <= 1'b1;
      end
    end
  end


endmodule

module InstructionMemory (
  input  wire [9:0]    io_fetchAddr,
  output wire [255:0]  io_fetchData,
  input  wire          io_write_valid,
  input  wire [9:0]    io_write_payload_addr,
  input  wire [255:0]  io_write_payload_data,
  input  wire          clk,
  input  wire          reset
);

  reg        [255:0]  mem_spinal_port0;
  wire                _zz_mem_port;
  wire                _zz_io_fetchData;
  reg                 _zz_1;
  reg [255:0] mem [0:1023];

  assign _zz_io_fetchData = 1'b1;
  always @(posedge clk) begin
    if(_zz_io_fetchData) begin
      mem_spinal_port0 <= mem[io_fetchAddr];
    end
  end

  always @(posedge clk) begin
    if(_zz_1) begin
      mem[io_write_payload_addr] <= io_write_payload_data;
    end
  end

  always @(*) begin
    _zz_1 = 1'b0;
    if(io_write_valid) begin
      _zz_1 = 1'b1;
    end
  end

  assign io_fetchData = mem_spinal_port0;

endmodule

